package com.yeyamo_mobile.api.payment_service.infrastructure.persistence;
import java.util.*;import org.springframework.data.jpa.repository.*;import jakarta.persistence.LockModeType;
public interface PaymentRepository extends JpaRepository<PaymentEntity,UUID>,JpaSpecificationExecutor<PaymentEntity>{Optional<PaymentEntity>findBySourceTypeAndSourceId(com.yeyamo_mobile.api.payment_service.domain.PaymentSourceType type,UUID id);default Optional<PaymentEntity>findByBookingId(UUID id){return findBySourceTypeAndSourceId(com.yeyamo_mobile.api.payment_service.domain.PaymentSourceType.BOOKING,id);}Optional<PaymentEntity>findByIdempotencyKey(String key);Optional<PaymentEntity>findByProviderPaymentId(String id);List<PaymentEntity>findByUserIdOrderByCreatedAtDesc(String user);
 @Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from PaymentEntity p where p.sourceType=:type and p.sourceId=:sourceId")Optional<PaymentEntity>findBySourceLocked(com.yeyamo_mobile.api.payment_service.domain.PaymentSourceType type,UUID sourceId);
 default Optional<PaymentEntity>findByBookingIdLocked(UUID id){return findBySourceLocked(com.yeyamo_mobile.api.payment_service.domain.PaymentSourceType.BOOKING,id);}
 @Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from PaymentEntity p where p.id=:id")Optional<PaymentEntity>findLockedById(UUID id);
 @Query(value="SELECT provider_payment_id FROM payments WHERE provider_payment_id IS NOT NULL GROUP BY provider_payment_id HAVING COUNT(*)>1",nativeQuery=true)List<String>duplicateProviderTransactions();}
